<?php declare(strict_types=1); namespace Database\Schema; use Core\Database\Schema\Blueprint; use Core\Database\Schema\SchemaDefinition; class BlogTranslationsSchema extends SchemaDefinition { protected string $table = 'blog_translations'; public function define(Blueprint $table): void { $table->id(); $table->foreignId('blog_id'); $table->string_50('locale')->index(); $table->string_255('title'); $table->string_255('excerpt')->nullable(); $table->long_text('content')->nullable(); $table->foreign('blog_id')->references('id')->on('blogs')->onDelete('CASCADE'); $table->unique('blog_id', 'locale'); } } 